<script lang="ts">import{onMount}from'svelte';import{defaultDocument,type LabelDocument}from'../model.js';import type{EditorStore}from'../store.js';import{EditorDatabase,type RecentItem}from'../persistence/database.js';export let editor:EditorStore;const database=new EditorDatabase();let documents:LabelDocument[]=[];let recent:RecentItem[]=[];let status='';onMount(refresh);async function refresh(){documents=await database.listDocuments();recent=await database.listRecent()}async function save(){await database.saveDocument($editor.document);await database.saveRecent({id:$editor.document.id,kind:'document',openedAt:new Date().toISOString()});await refresh();status=`Saved ${$editor.document.title} to this browser.`}async function open(document:LabelDocument){editor.replace(structuredClone(document));await database.saveRecent({id:document.id,kind:'document',openedAt:new Date().toISOString()});await refresh();status=`Opened ${document.title} from this browser.`}function create(){editor.replace(defaultDocument());status='Created a new unsaved label.'}async function rename(document:LabelDocument,title:string){const copy=structuredClone(document);copy.title=title.trim()||document.title;copy.modifiedAt=new Date().toISOString();await database.saveDocument(copy);await refresh();status=`Renamed label to ${copy.title}.`}async function remove(document:LabelDocument){await database.removeDocument(document.id);await refresh();status=`Removed ${document.title} from browser storage.`}</script>
<section><h2>Document library</h2><div class="actions"><button on:click={create}>New label</button><button on:click={save}>Save to browser</button><button on:click={refresh}>Refresh</button></div><p aria-live="polite">{status}</p>{#if documents.length}<ul>{#each documents as document}<li><button on:click={()=>open(document)}>{document.title}</button><input aria-label={`Rename ${document.title}`} value={document.title} on:change={e=>rename(document,e.currentTarget.value)}><button aria-label={`Delete ${document.title}`} on:click={()=>remove(document)}>Delete</button><small>{document.media.width} × {document.media.height} mm · {new Date(document.modifiedAt).toLocaleString()}</small>{#if recent.some(item=>item.kind==='document'&&item.id===document.id)}<span>recent</span>{/if}</li>{/each}</ul>{:else}<p>No explicitly saved browser documents yet. Autosave recovery remains active.</p>{/if}</section>
<style>section{padding:.75rem;border-top:1px solid var(--mble-border,#ddd)}h2{font-size:.8rem;text-transform:uppercase}.actions{display:flex;gap:.35rem;flex-wrap:wrap}ul{list-style:none;padding:0;margin:.5rem 0}li{display:grid;grid-template-columns:1fr auto;gap:.15rem .4rem;padding:.35rem 0;border-bottom:1px solid var(--mble-border,#eee)}li button{text-align:left}small{grid-column:1;color:var(--mble-text-muted,#666)}li span{font-size:.68rem;color:var(--mble-accent,#236447)}</style>
